#!/usr/bin/env python3
"""UI3 tuning controls use native permissions/budget; no other module changes."""
from pathlib import Path
p=Path('overlay/main/web/index.html');s=p.read_text()
s=s.replace('id="v2turbo" disabled title="30 Вт не проверены на физическом Gamma"','id="v2turbo" onclick="turboOpen()" title="Расширенный разгон"').replace('<span>TURBO · заблокирован</span>','<span>TURBO · эксперимент</span>')
s=s.replace('TURBO недоступен: допустимость 30 Вт на этом устройстве не подтверждена.','Расширенные пределы задаются в разделе разблокировки.')
s=s.replace('BTC HUNTER / ULTIMATE 2.0','BTC HUNTER / ULTIMATE 2.0 · UI3')
s=s.replace('name="pcap"','id="turboPower" name="pcap"')
panel='''<div id="turboPanel"><h3>Автоматический поиск TURBO1000</h3><p class="note">Потолок исследования, не принудительная частота. Ручную частоту и лимит мощности задавайте в единственной штатной форме выше. Разблокировка сохраняется; запуск поиска — отдельное действие.</p><div class="row"><div><label>Максимум поиска, МГц</label><input id="turboMax" type="number" min="800" max="1000" step="1" value="1000"></div><div><label>Номинальная мощность БП, Вт</label><input id="turboPsu" type="number" min="15" max="120" step="1" value="30"></div><div><label>Номинальный ток БП 5 В, А</label><input id="turboAmps" type="number" min="3" max="24" step="0.1" value="6"></div></div><p class="note">Номинал БП вводит пользователь; прошивка его не измеряет. Потребление всей платы оценивается как TPS Pout + штатный запас. Дополнительно резервируются 10% номинала (не менее 2 Вт), 0,5 А и 1,5 Вт погрешности. Более мощный БП не поднимает пользовательский предел выше 30 Вт.</p><div class="btns"><button type="button" class="btn alt" id="turboConfig" onclick="turboConfigure()">Сохранить параметры БП и поиска</button><button type="button" class="btn" id="turboStart" onclick="window.turboStart()" disabled>Подтвердить и начать</button><button type="button" class="btn alt" id="turboStop" onclick="window.turboStop()" disabled>Остановить и вернуть штатный режим</button></div><p class="info" id="turboStatus">Загрузка статуса…</p><p class="note">Для старта нужны 30 минут свежей стабильной точки, принятая работа V1 и штатный тюнер в Locked. Перезагрузка сохраняет разрешение и БП, но не запускает эксперимент; сохранённая частота выше штатной возвращается к безопасной стартовой точке до ручного подтверждения.</p><details><summary>Adaptive Silicon Map</summary><div id="turboMap" class="note"></div></details><details><summary>Последние испытанные ступени</summary><div id="turboTrials" class="note"></div></details></div>'''
a='<button type="button" class="btn alt" id="ocbtn" onclick="ocToggle()">--</button></div>'
assert s.count(a)==1;s=s.replace(a,a+panel)
s=s.replace("$('v2turbo').disabled=true;",'turboRender();')
s=s.replace('function v2render(s){',"function v2render(s){if(!document.hidden&&(cur==='tuning'||cur==='dash'))turboLoad();")
s=s.replace("(cap>0?Math.min(25,cap):25)+' Вт", "(turboData?.effectivePower??cfg.limits?.effectivePower??'—')+' Вт")
js=r'''
let turboData=null,turboBusy=false,turboCommand=false,turboPoll=0,turboInitial=false;
const turboReasons={none:'Ожидание',frequency:'Предел исследования',power:'Мощность',temperature:'Температура/охлаждение',supply:'Питание/VIN/ток',errors:'Ошибки ASIC или полезная работа',network:'Сеанс/ответ пула',pll:'Запись/проверка PLL',user:'Остановка пользователем',settings:'Изменение настроек',storage:'Ошибка NVS',telemetry:'Недостоверные датчики',insufficient_accepted_work:'Недостаточно принятой работы',controller:'Watchdog тюнера',voltage:'Предел напряжения',fault_hold:'Защита'};
const budgetReasons={user_limit:'Пользовательский предел',invalid_psu:'Некорректный номинал БП',psu_current_reserve_and_input_uncertainty:'Резерв тока БП 0,5 А и погрешность входной мощности',psu_power_reserve_and_input_uncertainty:'Резерв мощности БП 10% и погрешность входной мощности',psu_not_verified:'БП ещё не оценён под нагрузкой: дополнительный резерв 10%',voltage_sag:'Просадка VIN: дополнительный резерв 10%',thermal_headroom:'Температурный запас: дополнительный резерв 10%'};
function turboRender(){const d=turboData,armed=!!d?.armed;const button=$('v2turbo');if(button)button.disabled=!d||turboCommand;$('turboStart').disabled=!d?.unlocked||armed||turboCommand;$('turboStop').disabled=!armed||turboCommand;$('turboConfig').disabled=!d?.unlocked||armed||turboCommand;for(const id of ['turboMax','turboPsu','turboAmps'])$(id).disabled=armed||turboCommand;
 if(d){const L=cfg.limits;if(L){L.maxFreq=d.activeMaxFreq;L.maxPower=d.userMaxPower;L.effectivePower=d.effectivePower;for(const el of [document.querySelector('[name=freq]'),$('fnum')])el.max=L.maxFreq;$('turboPower').max=L.maxPower;$('lims').innerHTML=[[L.maxFreq+' МГц','Предел активного режима'],[L.minMv+'–'+L.maxMv+' мВ','Напряжение'],[L.chipCeil+'°C / '+L.chipCrit+'°C','Предел / аварийный стоп ASIC'],[L.vrCeil+'°C / '+L.vrCrit+'°C','Предел / аварийный стоп VRM'],[L.maxPower+' Вт','Пользовательский максимум'],[(L.boardMaxPower??'—')+' Вт','Штатный электрический лимит платы'],[(cfg.overclock?.cutoffPower??'—')+' Вт','Аварийная отсечка'],[d.effectivePower+' Вт','Расчётный бюджет поиска']].map(x=>'<div><b>'+x[0]+'</b><span>'+x[1]+'</span></div>').join('');}
 const states=['Выключен','В очереди','Измерение','Удержание лучшей точки','Остановлен','Откат'];$('turboStatus').textContent=(states[d.state]||'Статус')+' · поиск до '+d.maxFreq+' МГц · PLL '+d.appliedFreq+' МГц · запрос '+d.requestedPower+' Вт / бюджет '+d.effectivePower+' Вт · '+(budgetReasons[d.budgetReason]||d.budgetReason)+' · '+(turboReasons[d.reason]||d.reason);}
 else $('turboStatus').textContent='TURBO API недоступен';
 const map=$('turboMap');map.textContent='';for(const point of d?.points||[]){const row=document.createElement('p');row.textContent=point.frequency+' МГц / '+point.millivolts+' мВ · ASIC '+point.asicGHs+' GH/s · принятая работа '+point.acceptedGHs+' GH/s · пик '+point.watts+' Вт';map.append(row)}if(!map.childNodes.length)map.textContent='Нет измеренных точек';
 const trials=$('turboTrials');trials.textContent='';for(const t of d?.trials||[]){const row=document.createElement('p');row.textContent=t[0]+' МГц / '+t[1]+' мВ · '+t[2]+' GH/s · '+t[3]+' Вт · '+(['стабильно','ошибки','температура','мощность','прервано'][t[4]]||t[4]);trials.append(row)}
 const form=document.querySelector('#tuning form');if(form)for(const el of form.querySelectorAll('input,select,button'))if(!el.closest('#turboPanel')&&el.id!=='ocbtn')el.disabled=armed;
}
async function turboLoad(force=false){if(turboBusy||(!force&&Date.now()-turboPoll<15000))return;turboBusy=true;turboPoll=Date.now();try{turboData=await readJson('/api/turbo');if(!turboInitial){$('turboMax').value=turboData.maxFreq;$('turboPsu').value=turboData.psuWatts;$('turboAmps').value=turboData.psuAmps;turboInitial=true}}catch(e){turboData=null}finally{turboBusy=false;turboRender()}}
function turboOpen(){tab('tuning');$('ocbtn').scrollIntoView({block:'start'});turboLoad(true)}
async function turboConfigure(){const body={action:'configure',psuWatts:+$('turboPsu').value,psuAmps:+$('turboAmps').value,maxFreq:+$('turboMax').value,powerLimit:+$('turboPower').value||30};return turboSend(body)}
async function turboStart(){if(!turboData?.unlocked||turboData.armed||turboCommand)return;const maxFreq=+$('turboMax').value,powerLimit=+$('turboPower').value;if(!Number.isInteger(maxFreq)||maxFreq<800||maxFreq>1000||!Number.isInteger(powerLimit)||powerLimit<18||powerLimit>30)return toast('Проверьте пределы');if(prompt('Ручной эксперимент с прогревом, повторными измерениями и откатом. Введите TURBO1000.')!=='TURBO1000')return;if(!await turboConfigure())return;await turboSend({enabled:true,confirm:'TURBO1000',maxFreq,powerLimit})}
async function turboStop(){return turboSend({enabled:false})}
async function turboSend(body){if(turboCommand)return false;turboCommand=true;turboRender();try{const r=await fetch('/api/turbo',{method:'POST',body:JSON.stringify(body)});if(!r.ok)throw Error(await r.text());await turboLoad(true);return true}catch(e){toast('TURBO: '+e.message);return false}finally{turboCommand=false;turboRender()}}
ocUi=function(){const o=cfg.overclock;if(!o)return;$('ocst').textContent=o.active?'Расширенный':o.unlocked?'Приостановлен защитой':o.available?'Штатный':'Недоступно';$('ocbtn').style.display='';$('ocbtn').disabled=!o.available&&!o.unlocked;$('ocbtn').textContent=o.unlocked?'Отключить расширенный разгон':'Включить расширенный разгон';$('ocnote').textContent=o.available?'Разрешение сохраняется. Программный экспериментальный потолок '+cfg.limits.maxFreq+' МГц; напряжение до '+cfg.limits.maxMv+' мВ; пользовательский предел '+cfg.limits.maxPower+' Вт. Это не подтверждение физического запаса платы.':'Нет поддержки Gamma/BM1370 или experimental board profile. Защиты не меняются.';};
ocToggle=async function(){const o=cfg.overclock;if(o.unlocked){if(turboData?.armed){if(!await turboStop())return;for(let i=0;i<15&&turboData?.armed;i++){await new Promise(r=>setTimeout(r,1000));await turboLoad(true)}if(turboData?.armed)return toast('Дождитесь безопасного отката');}if(await act('/api/settings',JSON.stringify({overclock:false})))await loadCfg();}else{if(prompt('Расширенный разгон до программного потолка. Защиты сохраняются; максимум не устанавливается. Введите OVERCLOCK.')!=='OVERCLOCK')return;if(await act('/api/settings',JSON.stringify({overclock:true,confirm:'OVERCLOCK'})))await loadCfg();}await turboLoad(true);};
const stockHeadroom=headroom;headroom=function(S){if(!turboData?.unlocked)return stockHeadroom(S);const d=turboData,t=S.tuner;$('hrst').textContent=d.armed?'Исследование '+(t?.progress??0)+'%':'Результат';$('hrnote').textContent='Применённая PLL '+d.appliedFreq+' МГц / '+(S.coreMv??'—')+' мВ · лучшая '+d.bestFreq+' МГц / '+d.bestMv+' мВ, '+d.bestGHs+' GH/s, '+d.bestWatts+' Вт · '+(turboReasons[d.reason]||d.reason);$('hrtoml').style.display=$('hrbtns').style.display='none';};
'''
a='a8init();loadCfg();tick();';assert s.count(a)==1;s=s.replace(a,js+'\n'+a);p.write_text(s)
